import{_ as n,o as t,c as a,a3 as s}from"./chunks/framework.BlfGB29P.js";const i="/images/logic-studio/user-guide/blocks-a-de.png",p=JSON.parse('{"title":"Blocks A","description":"","frontmatter":{},"headers":[],"relativePath":"projects/logic-studio/user-guide/blocks-a.md","filePath":"projects/logic-studio/user-guide/blocks-a.md","lastUpdated":1794771019000}'),r={name:"projects/logic-studio/user-guide/blocks-a.md"};function o(l,e,d,u,h,c){return t(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="blocks-a" tabindex="-1">Blocks A <a class="header-anchor" href="#blocks-a" aria-label="Permalink to &quot;Blocks A&quot;">​</a></h1><h2 id="erstes-beispiel" tabindex="-1">Erstes Beispiel <a class="header-anchor" href="#erstes-beispiel" aria-label="Permalink to &quot;Erstes Beispiel&quot;">​</a></h2><p>Die Beispielautomation schaltet das Flurlicht ein, sobald der Bewegungssensor <code>on</code> meldet.</p><ol><li>Wähle <strong>Neues Projekt → Blocks A</strong> und gib dem Projekt einen Namen. Auf der Fläche steht der Block <strong>Automation</strong>.</li><li>Öffne <strong>Auslöser</strong> und ziehe den Zustandsblock in <strong>Wenn</strong>. Im Bild steht <code>binary_sensor.flur_bewegung</code> mit dem Zielzustand <code>on</code>. Wähle auf deinem System deinen Testhelfer oder Sensor.</li><li>Öffne <strong>Aktionen</strong> und ziehe den Schaltblock in <strong>Dann</strong>. Im Bild steht <code>light.flur</code> auf <strong>einschalten</strong>. Für deinen ersten Versuch kannst du einen zweiten Testhelfer als Ziel verwenden. <strong>Nur wenn</strong> bleibt in diesem Beispiel leer.</li><li>Klicke auf das Fähnchen <strong>Blöcke prüfen</strong>. Wenn die Prüfung erfolgreich ist, wähle <strong>Als HA-YAML öffnen</strong>. Kontrolliere im Entwurf <code>triggers</code> und <code>actions</code>, bevor du exportierst.</li></ol><p><a href="/images/logic-studio/user-guide/blocks-a-de.png"><img src="'+i+'" alt="Blocks A mit Zustandsauslöser in Wenn und Schaltaktion in Dann"></a></p><h2 id="funktionen" tabindex="-1">Funktionen <a class="header-anchor" href="#funktionen" aria-label="Permalink to &quot;Funktionen&quot;">​</a></h2><h3 id="blockpalette-und-anschlusse" tabindex="-1">Blockpalette und Anschlüsse <a class="header-anchor" href="#blockpalette-und-anschlusse" aria-label="Permalink to &quot;Blockpalette und Anschlüsse&quot;">​</a></h3><p>Wähle einen Block aus und setze ihn an die passende Stelle. Die Form zeigt, ob er einen Wert liefert oder eine Aktion ausführt.</p><h3 id="ausloser-und-bedingungen" tabindex="-1">Auslöser und Bedingungen <a class="header-anchor" href="#ausloser-und-bedingungen" aria-label="Permalink to &quot;Auslöser und Bedingungen&quot;">​</a></h3><p>Der Auslöser startet die Automation. Eine Bedingung prüft zum Beispiel, ob der zweite Helfer bereits aus ist.</p><h3 id="aktionen-und-reihenfolge" tabindex="-1">Aktionen und Reihenfolge <a class="header-anchor" href="#aktionen-und-reihenfolge" aria-label="Permalink to &quot;Aktionen und Reihenfolge&quot;">​</a></h3><p>Stecke Aktionen untereinander. Home Assistant führt sie in der exportierten Reihenfolge aus.</p><h3 id="ha-auswahl" tabindex="-1">HA-Auswahl <a class="header-anchor" href="#ha-auswahl" aria-label="Permalink to &quot;HA-Auswahl&quot;">​</a></h3><p>Wähle eine Entität, Aktion oder ein Geräte-, Bereichs-, Label- oder Etagentarget. Im YAML erkennst du das Ziel am passenden ID-Feld.</p><h3 id="ha-yaml-entwurf" tabindex="-1">HA-YAML-Entwurf <a class="header-anchor" href="#ha-yaml-entwurf" aria-label="Permalink to &quot;HA-YAML-Entwurf&quot;">​</a></h3><p>Öffne die erzeugte Automation als YAML-Entwurf. Der Entwurf zeigt den Namen des Quellprojekts.</p><h3 id="export" tabindex="-1">Export <a class="header-anchor" href="#export" aria-label="Permalink to &quot;Export&quot;">​</a></h3><p>Prüfe das YAML und übernimm es in Home Assistant. Dort kannst du einen echten Auslöser und den Automations-Trace prüfen.</p><h2 id="wenn-etwas-nicht-klappt" tabindex="-1">Wenn etwas nicht klappt <a class="header-anchor" href="#wenn-etwas-nicht-klappt" aria-label="Permalink to &quot;Wenn etwas nicht klappt&quot;">​</a></h2><p>Wenn die Zielauswahl leer ist, kontrolliere, ob es auf dem verbundenen HA-System einen passenden Eintrag gibt.</p>',20)])])}const f=n(r,[["render",o]]);export{p as __pageData,f as default};
